<?php
namespace App\Models;
use App\Models\Concerns\BelongsToWorkspace;use Illuminate\Database\Eloquent\Model;use Illuminate\Database\Eloquent\Factories\HasFactory;
class Agent extends Model {use HasFactory,BelongsToWorkspace;protected $fillable=['workspace_id','name','slug','description','avatar_path','instructions','status','model_connection_id','model','default_effort','max_steps','max_runtime_seconds','max_cost_usd','policy','settings'];protected function casts():array{return ['policy'=>'array','settings'=>'array','max_cost_usd'=>'decimal:4'];}public function modelConnection(){return $this->belongsTo(ModelConnection::class);}public function runs(){return $this->hasMany(AgentRun::class);}public function schedules(){return $this->hasMany(AgentSchedule::class);}public function skills(){return $this->belongsToMany(Skill::class);}public function connectors(){return $this->belongsToMany(ConnectorConnection::class,'agent_connector')->withPivot('allowed_actions');}public function memories(){return $this->hasMany(AgentMemory::class);} }
